from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 7))
    m = draw(st.integers(1, 10))
    choice = draw(st.integers(0, 3))
    if choice == 0:
        a = [draw(st.integers(0, 10**9)) for _ in range(n)]
    elif choice == 1:
        a = [draw(st.integers(0, 5)) for _ in range(n)]
    elif choice == 2:
        v = draw(st.integers(0, 10**9))
        a = [v] * n
    else:
        a = [draw(st.sampled_from([0, m, m - 1 if m > 1 else 0, 10**9])) for _ in range(n)]
    return f"{n} {m}\n{' '.join(map(str, a))}\n"

def validate(inp):
    try:
        t = inp.split()
        if len(t) < 2:
            return False
        n, m = int(t[0]), int(t[1])
        a = [int(x) for x in t[2:]]
        if not (1 <= n <= 2 * 10**5 and 1 <= m <= 2 * 10**5):
            return False
        if len(a) != n:
            return False
        return all(0 <= x <= 10**9 for x in a)
    except Exception:
        return False

def ref(inp):
    t = inp.split()
    n, m = int(t[0]), int(t[1])
    a = [int(x) for x in t[2:2 + n]]
    total = 0
    for l in range(n):
        for r in range(l, n):
            s = 0
            for i in range(l, r + 1):
                s += a[i]
            total += s % m
    return str(total)
